\title{Partial Laplacian Spectra, Threshold Graphs, and the Brouwer Equality Problem}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
For a finite simple graph $G$ on $n$ vertices with $m$ edges, let
$\lambda_1 \ge \lambda_2 \ge \cdots \ge \lambda_n \ge 0$ be the eigenvalues of its
Laplacian matrix $L = D - A$, and let $s_k(G) = \sum_{i=1}^k \lambda_i$ be the sum
of the $k$ largest eigenvalues. Brouwer's conjecture asserts
$s_k(G) \le m + \binom{k+1}{2}$ for all $1 \le k \le n$, with the extremal graphs
conjectured to be exactly the threshold graphs of clique number $k+1$. We develop
the exact, unconditional infrastructure surrounding this problem. We prove that
$L$ is symmetric and positive semidefinite; establish the trace identity
$s_n(G) = 2m$; derive monotonicity of the partial sums, the global ceiling
$s_k(G) \le 2m$, and saturation $s_k(G) = 2m$ for $k \ge n$; and give a
self-contained creation-sequence model of threshold graphs, identifying the two
boundary sequences with the complete and empty graphs. We record the equality
target as an explicit predicate and characterize it completely on the edgeless
boundary of the threshold family, showing that the empty graph attains the bound
at level $k$ iff $k = 0$. We then explain precisely how the full biconditional
reduces to the Grone--Merris--Bai majorization theorem and the conjugate-degree
description of threshold spectra, and we state four conjectures charting the route
to the complete characterization.
\end{abstract}

\maketitle

\section{Introduction}

The Laplacian matrix of a graph is one of the most information-dense objects in
combinatorics. Its spectrum controls connectivity, mixing times of random walks,
the number of spanning trees (Kirchhoff's matrix--tree theorem), expansion and cut
structure (Cheeger-type inequalities), and the dynamics of diffusion and
synchronization on networks. A recurring theme is to bound \emph{sums of the
largest Laplacian eigenvalues}, since these dominate worst-case behavior in many
of these settings.

In 2007 Brouwer proposed a remarkably clean upper bound for the sum of the $k$
largest Laplacian eigenvalues:
\begin{equation}\label{eq:B}
  s_k(G) \le m + \binom{k+1}{2}, \qquad 1 \le k \le n. \tag{B}
\end{equation}
Despite intense study, \eqref{eq:B} remains open in general, though it is confirmed
for numerous families (trees, graphs with at most a prescribed number of edges,
split graphs, and others). The \emph{equality} form of the conjecture is even more
structurally revealing: equality in \eqref{eq:B} is conjectured to hold exactly for
threshold graphs whose clique number is $k+1$.

This paper isolates and proves the unconditional backbone of the equality problem
and locates precisely the single hard step that remains.

\section{Preliminaries and notation}

Throughout, $G$ is a finite simple graph on $n$ labeled vertices
$\{1, \dots, n\}$, with edge set $E(G)$ and $m = |E(G)|$. We write $\deg(v)$ for
the degree of vertex $v$.

\begin{definition}[Laplacian]
The adjacency matrix $A \in \mathbb{R}^{n \times n}$ has $A_{ij} = 1$ if
$\{i,j\} \in E(G)$ and $0$ otherwise (so $A_{ii} = 0$). The degree matrix $D$ is
diagonal with $D_{ii} = \deg(i)$. The \emph{Laplacian matrix} is $L = D - A$.
\end{definition}

\begin{definition}[Clique number]
The \emph{clique number} $\omega(G)$ is the number of vertices in a largest
complete subgraph of $G$.
\end{definition}

\section{The Laplacian is symmetric and positive semidefinite}

\begin{proposition}[Symmetry]
$L$ is symmetric: $L^{\top} = L$.
\end{proposition}
\begin{proof}
Both $D$ and $A$ are symmetric, so $L = D - A$ is symmetric.
\end{proof}

\begin{proposition}[Positive semidefiniteness]\label{prop:psd}
For every $x \in \mathbb{R}^n$,
\[
  x^{\top} L x = \sum_{\{i,j\}\in E(G)} (x_i - x_j)^2 \ge 0.
\]
In particular $L$ is positive semidefinite.
\end{proposition}
\begin{proof}
Expand $x^\top L x = \sum_i \deg(i)\,x_i^2 - \sum_{i,j} A_{ij} x_i x_j$. Each edge
$\{i,j\}$ contributes $x_i^2 + x_j^2$ to the first sum and $-2 x_i x_j$ to the
second, totaling $(x_i - x_j)^2$. Summing over edges gives the stated identity,
which is nonnegative.
\end{proof}

\begin{corollary}[Real nonnegative spectrum]\label{cor:spectrum}
Since $L$ is real symmetric its eigenvalues are real, and since it is positive
semidefinite they are nonnegative. Ordered decreasingly,
$\lambda_1(G) \ge \cdots \ge \lambda_n(G) \ge 0$.
\end{corollary}

\section{Partial spectral sums and the trace identity}

\begin{definition}[Partial spectral sum]
For $k \in \mathbb{N}$, $s_k(G) = \sum_{i=1}^{\min(k,n)} \lambda_i(G)$, the sum of
the $k$ largest Laplacian eigenvalues.
\end{definition}

\begin{theorem}[Trace identity]\label{thm:trace}
$\sum_{i=1}^n \lambda_i(G) = 2m$; equivalently $s_n(G) = 2m$.
\end{theorem}
\begin{proof}
For a real symmetric matrix the trace equals the sum of eigenvalues, so
$\sum_i \lambda_i(G) = \trace(L) = \trace(D) - \trace(A)$. The adjacency matrix has
zero diagonal, hence $\trace(A) = 0$, while $\trace(D) = \sum_v \deg(v)$. By the
handshake lemma $\sum_v \deg(v) = 2m$, so $\trace(L) = 2m$.
\end{proof}

\begin{theorem}[Monotonicity]\label{thm:mono}
The map $k \mapsto s_k(G)$ is nondecreasing.
\end{theorem}
\begin{proof}
For $k \le \ell$, $s_\ell(G) - s_k(G) = \sum_{i=k+1}^{\min(\ell,n)} \lambda_i(G) \ge 0$
by Corollary~\ref{cor:spectrum}.
\end{proof}

\begin{theorem}[Global ceiling]\label{thm:ceiling}
For every $k$, $s_k(G) \le 2m$.
\end{theorem}
\begin{proof}
$s_k(G) \le \sum_{i=1}^n \lambda_i(G) = 2m$ by nonnegativity and
Theorem~\ref{thm:trace}.
\end{proof}

\begin{theorem}[Nonnegativity]
For every $k$, $s_k(G) \ge 0$.
\end{theorem}
\begin{proof}
A finite sum of nonnegative eigenvalues.
\end{proof}

\begin{theorem}[Saturation]
For $k \ge n$, $s_k(G) = 2m$.
\end{theorem}
\begin{proof}
For $k \ge n$ the sum ranges over all $n$ eigenvalues, so $s_k(G) = s_n(G) = 2m$
by Theorem~\ref{thm:trace}.
\end{proof}

\section{Threshold graphs via creation sequences}

\begin{definition}[Creation sequence and threshold graph]
A \emph{creation sequence} is a map $b : \{1,\dots,n\} \to \{\mathtt{true},
\mathtt{false}\}$ ($\mathtt{true} =$ dominating, $\mathtt{false} =$ isolated). The
associated \emph{threshold graph} $T_b$ has distinct vertices $i, j$ adjacent iff
$b(\max(i,j)) = \mathtt{true}$. This relation is symmetric and loopless, so $T_b$
is a simple graph.
\end{definition}

Each vertex at birth connects either to all existing vertices (dominating) or to
none (isolated). Threshold graphs are exactly the graphs with no induced $P_4$,
$C_4$, or $2K_2$.

\begin{theorem}[Complete-graph boundary]
If $b$ is the all-dominating sequence ($b \equiv \mathtt{true}$), then $T_b = K_n$.
\end{theorem}
\begin{proof}
Every distinct pair satisfies $b(\max(i,j)) = \mathtt{true}$, so all pairs are
adjacent, giving $K_n$.
\end{proof}

\begin{theorem}[Empty-graph boundary]
If $b$ is the all-isolated sequence ($b \equiv \mathtt{false}$), then
$T_b = \overline{K_n}$.
\end{theorem}
\begin{proof}
No pair satisfies $b(\max(i,j)) = \mathtt{true}$, so the graph is edgeless.
\end{proof}

\section{The Brouwer equality predicate and its edgeless boundary}

\begin{definition}[Brouwer bound and equality predicate]
The \emph{Brouwer bound} at level $k$ is $\beta_k(G) = m + \binom{k+1}{2}$. We say
$G$ satisfies \emph{Brouwer equality at level $k$}, written $\mathrm{BE}(G,k)$, if
$s_k(G) = \beta_k(G)$.
\end{definition}

\begin{conjecture}[Equality characterization]\label{conj:char}
For $1 \le k \le n-1$, $\mathrm{BE}(G,k)$ holds iff $G$ is a threshold graph with
clique number $\omega(G) = k+1$.
\end{conjecture}

\begin{lemma}[Silent spectrum of the empty graph]\label{lem:empty}
For $\overline{K_n}$, every Laplacian eigenvalue is $0$; hence $s_k = 0$ for all
$k$.
\end{lemma}
\begin{proof}
Here $L = 0$. Alternatively, $0 \le s_k \le 2m = 0$ since $m = 0$.
\end{proof}

\begin{theorem}[Edgeless equality boundary]\label{thm:edgeless}
For $\overline{K_n}$ and any $k$, $\mathrm{BE}(\overline{K_n}, k) \iff k = 0$.
\end{theorem}
\begin{proof}
Here $m = 0$, so $\beta_k = \binom{k+1}{2}$, while $s_k = 0$ by
Lemma~\ref{lem:empty}. Thus equality holds iff $\binom{k+1}{2} = \tfrac{k(k+1)}{2}
= 0$, i.e. iff $k = 0$.
\end{proof}

\begin{corollary}
For every $k \ge 1$ the edgeless graph fails Brouwer equality by the full amount
$\beta_k - s_k = \binom{k+1}{2}$.
\end{corollary}

Theorem~\ref{thm:edgeless} confirms Conjecture~\ref{conj:char} on this boundary:
$\overline{K_n}$ is a threshold graph with $\omega = 1$, so the predicted
saturation level is $k = \omega - 1 = 0$.

\section{Reduction of the full characterization to majorization}

Let $d_1 \ge \cdots \ge d_n$ be the degrees in decreasing order, a partition of
$2m$, and let $d^*$ be its conjugate (transpose) partition,
$d_j^* = \#\{i : d_i \ge j\}$.

\begin{theorem}[Grone--Merris--Bai; cited]\label{thm:gmb}
For every graph $G$ and $1 \le k \le n$,
$s_k(G) = \sum_{i=1}^k \lambda_i(G) \le \sum_{j=1}^k d_j^*(G)$, with equality at
$k = n$.
\end{theorem}

\begin{theorem}[Merris; threshold spectra, cited]\label{thm:merris}
A graph is a threshold graph iff its Laplacian spectrum equals its conjugate
degree sequence: $\lambda_i(G) = d_i^*(G)$ for all $i$.
\end{theorem}

For the extremal family $\sum_{j \le k} d_j^* = \beta_k$ precisely when $k+1$ is the
clique number. Combining Theorems~\ref{thm:gmb} and~\ref{thm:merris} yields the
conjectural picture: equality $s_k = \beta_k$ squeezes the spectrum against the
conjugate degree sequence, forcing exact conjugacy, i.e. the threshold property.
The monotonicity and ceiling results above provide the lower bracket, and
Theorem~\ref{thm:gmb} the upper bracket; the remaining gap is the majorization
tightness step at intermediate $k$.

\section{Algorithms}

\begin{algorithm}[Partial spectral sum]
Form $L = D - A$, compute its eigenvalues, sort decreasingly, and accumulate the
top $k$. Complexity $O(n^3)$; correctness by Corollary~\ref{cor:spectrum}.
\end{algorithm}

\begin{algorithm}[Threshold graph from a creation sequence]
Given $b \in \{0,1\}^n$, output $A_{ij} = [\,i \ne j \wedge b_{\max(i,j)} = 1\,]$.
Complexity $O(n^2)$.
\end{algorithm}

\begin{algorithm}[Conjugate degree sequence]
Given $d_1 \ge \cdots \ge d_n$, output $d_j^* = \#\{i : d_i \ge j\}$. Complexity
$O(n + \max_i d_i)$.
\end{algorithm}

\begin{algorithm}[Brouwer gap scan]
For each $1 \le k \le n-1$ compute $\beta_k(G) - s_k(G)$; a zero gap flags a
candidate extremal level, empirically testing Conjecture~\ref{conj:char}.
\end{algorithm}

\section{Worked examples}

\textbf{The path $P_3$ (three vertices, two edges).} With $m = 2$, the Laplacian
has spectrum $\{3,1,0\}$, so $s_1 = 3$, $s_2 = 4$, $s_3 = 4 = 2m$. The Brouwer
bounds are $\beta_1 = 3$, $\beta_2 = 5$. Since $s_1 = 3 = \beta_1$ and $P_3$ is the
star $K_{1,2}$ (a threshold graph with clique number $2$), saturation occurs at
$k = 1 = \omega - 1$, as predicted.

\textbf{The four-cycle $C_4$.} With $m = 4$, the spectrum is $\{4,2,2,0\}$, giving
$s_1 = 4 < 5$, $s_2 = 6 < 7$, $s_3 = 8 < 10$, and $s_4 = 8 = 2m$. As $C_4$ is a
forbidden induced subgraph, it is not a threshold graph and attains equality at no
level. Its degree sequence $(2,2,2,2)$ has conjugate $(4,4)$ with top-$2$ sum
$8 > 6 = s_2$, exhibiting strict majorization slack.

\textbf{The complete graph $K_4$.} With $m = 6$, the spectrum is $\{4,4,4,0\}$, so
$s_3 = 12 = 6 + 6 = \beta_3$: $K_4$ is a threshold graph with clique number $4$,
saturating at $k = 3 = \omega - 1$.

\section{Applications}

Sums of the largest Laplacian eigenvalues control quantitative behavior across
applied domains. In graph heat flow $\dot u = -Lu$, each mode decays at rate
$\lambda_i$, and $s_k$ measures the aggregate stiffness of the top $k$ modes. In
synchronization and consensus dynamics, stability margins are governed by the
Laplacian spectrum, and the extremal (threshold) configurations identify
worst-case topologies. In spectral clustering, the magnitude of the top
eigenvalues bounds embedding cost. Finally, the trace identity $s_n = 2m$ shows
that total spectral energy is fixed by the edge count, so robustness differences
among graphs with equal edge counts reduce entirely to how that fixed energy is
distributed across the spectrum --- the distributional question the Brouwer bound
constrains.

\section{Discussion}

The results cleanly separate the provable spine of the Brouwer equality problem
from its single hard core. Trace identity, positive semidefiniteness, monotonicity,
ceiling, and saturation are elementary consequences of linear algebra and the
handshake lemma; the threshold family is captured combinatorially by creation
sequences, with poles pinned to $K_n$ and $\overline{K_n}$; and the equality
predicate is resolved exactly on the edgeless boundary, matching the clique-number
prediction. The remaining difficulty is concentrated in the tightness of the
Grone--Merris--Bai majorization at intermediate $k$.

\section{Future directions}

\begin{conjecture}[Conjugate-degree spectrum of threshold graphs]
For every threshold graph, the multiset of Laplacian eigenvalues equals the
conjugate (transpose) of its degree partition. Each dominating step of the
creation sequence induces a uniform additive shift of the spectrum, so the
spectrum is read off the Ferrers diagram of the degree sequence, converting an
eigenvalue question into a partition-combinatorics induction.
\end{conjecture}

\begin{conjecture}[Saturation only at the clique boundary]
Among all graphs on $n$ vertices with $m$ edges, $s_k$ attains
$m + \binom{k+1}{2}$ exactly when the graph is a threshold graph whose clique
number is $k+1$. Both sides are majorization extremes, so equality forces the
spectrum to be exactly conjugate; the monotonicity and ceiling results here supply
the bracketing inequalities, leaving only the majorization-tightness step.
\end{conjecture}

\begin{conjecture}[Strict slack away from the extremal family]
For any non-threshold graph and any $1 \le k \le n-1$, the gap
$m + \binom{k+1}{2} - s_k$ is bounded below by a positive quantity depending only
on the number of induced obstructions ($P_4$, $C_4$, $2K_2$), since each forbidden
subgraph perturbs the Laplacian by a controllable rank-one amount.
\end{conjecture}

\begin{conjecture}[Edge-invariant rigidity of the total sum]
The identity $s_n = 2m$ is the unique linear spectral functional that is a graph
edge-invariant; every other top-$k$ sum genuinely depends on structure beyond $m$
for $1 \le k \le n-1$. The trace is the only symmetric function of the spectrum
that collapses to the diagonal, whose entries form the degree sequence summing to
$2m$.
\end{conjecture}

